/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void dst_bus_err_add (Dst_Bus_Error_Code code)
{  

  UInt8 ptr = (dst_bus_vars.err.count % DST_BUS_ERR_BUFF_SIZE) ;
 
  dst_bus_vars.err.code[ptr] = code ;

  dst_bus_vars.err.count++ ;

  dst_bus_vars.do_err_save = TRUE ;

}


